@Override public synchronized boolean consumeInvitation(
        String tenantId, String invitationId, Instant consumedAt) {
    Invitation value = invitation(tenantId, invitationId).orElse(null);
    if (value == null || value.confirmedAt().isEmpty() || value.consumedAt().isPresent()
